contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will try two calls: one from this contract (not jojoTeam) which must revert,
    // and one simulated by first setting jojoTeam to this contract via calling nothing —
    // since we cannot access or set jojoTeam directly, we instead treat the parameter
    // callerIsJojo to decide which call we expect to succeed. The test will call
    // c.newEmergencyOracle(...) and check revert behavior matches expectation.

    // Note: because the checker deploys a fresh C and jojoTeam is initially zero,
    // only a call from address(0) would match; but the intended specification is that
    // only the jojoTeam address can succeed. We encode that as: if callerIsJojo==false
    // then the call must revert; if callerIsJojo==true then the call must succeed.
    // The checker will explore inputs and states; the assertion ties the observed
    // revert flag to the provided callerIsJojo parameter.

    function run(bool callerIsJojo, string calldata desc) public payable {
        require(true);

        bool reverted;
        // Attempt the call and capture whether it reverts.
        try c.newEmergencyOracle(desc) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call succeeds (not reverted) iff callerIsJojo is true.
        // Additionally, when it succeeds, the created oracle's owner must be msg.sender
        // as signaled by the emitted event; however we cannot read events here. So the
        // invariant we assert is that if the call succeeded, then it must not revert,
        // and if it reverted then it indicates caller was not jojoTeam. We express the
        // property purely: reverted == (!callerIsJojo).
        assert(reverted == (!callerIsJojo));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that calling newEmergencyOracle(desc) either reverts, or returns (by emitting) a non-zero newly deployed EmergencyOracle address;
    // additionally the call must not change the public jojoTeam value of c.
    // Because we cannot observe events inside Solidity, we observe success by the call not reverting and then checking that address(c).balance is unchanged
    // and that jojoTeam value is equal before and after. The creation of a new contract increases total system balance only if value is sent,
    // but deployment here does not send Ether; so we only assert jojoTeam unchanged and that on non-revert the call succeeded (reverted==false).

    function run(string calldata desc) public payable {
        // no precondition on desc
        // read jojoTeam before
        address beforeTeam = c.jojoTeam();

        bool reverted;
        try c.newEmergencyOracle(desc) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read jojoTeam after
        address afterTeam = c.jojoTeam();

        // General rule: the call does not change jojoTeam (before == after).
        // This is a non-trivial invariant: creating a new EmergencyOracle should not alter C.jojoTeam.
        assert(beforeTeam == afterTeam);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We check: calling newEmergencyOracle(desc) may revert; if it does not revert then the public jojoTeam value of c remains equal to its pre-call value.
    // We cannot observe events directly here, so success is observed as non-revert. The rule is: the call does not mutate jojoTeam on success.
    function run(string calldata desc) public payable {
        // no precondition on desc
        // read jojoTeam before the call
        address beforeTeam = c.jojoTeam();

        bool reverted;
        try c.newEmergencyOracle(desc) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read jojoTeam after the call
        address afterTeam = c.jojoTeam();

        // General rule: either the call reverted, or jojoTeam stayed the same.
        assert(reverted || beforeTeam == afterTeam);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising newEmergencyOracle
    // Params: description string
    // Rule: either the call reverts, or the public jojoTeam remains unchanged and was not the zero address.
    function run(string calldata description) public payable {
        // no preconditions on description
        // read jojoTeam before the call
        address beforeTeam = c.jojoTeam();

        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterTeam = c.jojoTeam();

        // General rule: either the call reverted, or jojoTeam stayed the same and is non-zero
        assert(reverted || (beforeTeam == afterTeam && beforeTeam != address(0)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a description and attempt to call newEmergencyOracle.
    // Rule: either the call reverts, or jojoTeam is unchanged by the call.
    // We also record whether the call reverted so the assert is a general property over all inputs.
    function run(string calldata description) public payable {
        // no precondition on description
        // Observe jojoTeam before the call
        address beforeTeam = c.jojoTeam();

        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterTeam = c.jojoTeam();

        // General rule: the call either reverted, or jojoTeam stayed the same.
        assert(reverted || beforeTeam == afterTeam);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: caller address candidate for jojoTeam, description string
    function run(address caller, string calldata description) public payable {
        require(caller != address(0), "caller must be non-zero");

        // Make caller the jojoTeam by directly setting jojoTeam via calling C's fallback? Not possible.
        // But the checker deploys a fresh C and this test contract is the deployer; we can only interact via public surface.
        // However C has a public variable jojoTeam (getter). We cannot write it. So we instead reason about both cases:
        // If this contract is jojoTeam, the call should succeed and produce a NewEmergencyOracle event and an oracle whose owner is msg.sender (the test contract) and description matches input.
        // Otherwise the call must revert with "Caller is not the JOJO team".

        // We will attempt the call from this contract. Since messages to c come from this contract, the effective caller is address(this).
        // We record current jojoTeam to decide expected behavior.
        address jt = c.jojoTeam();

        // Try the call and capture whether it reverted.
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call (whether reverted or not) we can observe c.jojoTeam() and address(c).balance and public getters.
        // If this contract was jojoTeam at call time, then call must not revert and should have created a new EmergencyOracle with owner = address(this) and matching description.
        // The NewEmergencyOracle event isn't readable, so instead we check that a newly created EmergencyOracle contract exists at some address — but we cannot get it.
        // Instead we use observable guarantees: when newEmergencyOracle succeeds it deploys EmergencyOracle and emits event; it does not change jojoTeam.
        // So we assert: (jt == address(this)) implies (not reverted && c.jojoTeam() == jt).
        // And (jt != address(this)) implies reverted.

        assert( (jt == address(this) && !reverted && c.jojoTeam() == jt) || (jt != address(this) && reverted) );
    }

    receive() external payable { }
 }
